def max_unpooled_rps(port_low: int = 32768, port_high: int = 60999, time_wait_sec: int = 60) -> float:
    if port_high < port_low or time_wait_sec <= 0:
        raise ValueError('Invalid port range or TIME_WAIT duration')
    num_ports = port_high - port_low + 1
    return round(num_ports / time_wait_sec, 2)

def ports_needed_for_rps(rps: int, time_wait_sec: int = 60) -> int:
    if rps < 0 or time_wait_sec <= 0:
        raise ValueError('rps >= 0 and time_wait_sec > 0 required')
    return rps * time_wait_sec

def sockets_for_pooled_rps(target_rps: int, avg_latency_ms: float, max_rps_per_conn: float = 200.0) -> int:
    if target_rps <= 0 or avg_latency_ms <= 0:
        raise ValueError('RPS and latency must be positive')
    little = target_rps * (avg_latency_ms / 1000.0)
    return max(16, int(little * 1.5))

def total_4tuple_capacity(num_src_ips: int, num_dst_ips: int = 1, ports_per_ip: int = 64511) -> int:
    if num_src_ips <= 0 or num_dst_ips <= 0:
        raise ValueError('IP counts must be positive')
    return num_src_ips * num_dst_ips * ports_per_ip

def evaluate_close_strategy(use_keepalive_pool: bool, force_rst_linger: bool) -> str:
    if force_rst_linger:
        return 'REJECT_UNSAFE_ECONNRESET_AND_DATA_CORRUPTION'
    if use_keepalive_pool:
        return 'SAFE_PERSISTENT_POOL_ZERO_CHURN'
    return 'SAFE_TW_REUSE_AND_WIDE_PORTS'

def check_ephemeral_port_health(tw_count: int, port_range_size: int = 64511) -> str:
    if port_range_size <= 0:
        raise ValueError('port_range_size must be positive')
    ratio = tw_count / port_range_size
    if ratio >= 0.80:
        return 'PAGE_CRITICAL_PORT_EXHAUSTION'
    if ratio >= 0.60:
        return 'WARN_HIGH_TIME_WAIT_CHURN'
    return 'HEALTHY'
